array = [2, 4, 6, 8, 10, 12, 14]
target = 10   # not in the input: type it yourself
index, low, high = -1, 0, len(array) - 1
while low <= high:
    mid = (low + high) // 2
    if array[mid] == target:
        index = mid
        break
    elif target < array[mid]:
        high = mid - 1
    else:
        low = mid + 1
